<?php
function adminUser(): array { $u=user(); if($u['role']!=='admin')fail('Acesso restrito à administração.',403);return $u; }
function audit(int $admin,?int $business,string $action,string $reason): void { query('INSERT INTO admin_audit(admin_id,business_id,action,reason,created_at) VALUES(?,?,?,?,?)',[$admin,$business,$action,$reason,date('Y-m-d H:i:s')]); }
function mapUrl(array $d): string { $url=urlField($d,'maps_url');if(!$url)return ''; $host=strtolower(parse_url($url,PHP_URL_HOST)??'');$path=parse_url($url,PHP_URL_PATH)??'';if(parse_url($url,PHP_URL_SCHEME)!=='https' || !($host==='maps.app.goo.gl'||$host==='maps.google.com'||$host==='maps.google.com.br'||(($host==='www.google.com'||$host==='www.google.com.br'||$host==='google.com')&&str_starts_with($path,'/maps'))||($host==='goo.gl'&&str_starts_with($path,'/maps'))))fail('Cole um link HTTPS do Google Maps, como https://maps.app.goo.gl/…');return $url; }
function sarzedoNeighborhoods(): array { return ['Cachoeira','Santa Rita','Santo Antônio','Quintas da Lagoa','Jardim Anchieta','Riacho da Mata','Brasília','Bairro Santa Rosa','Jardim Vera Cruz','Cinira de Freitas','Santa Rosa','São Pedro','Imaculada da Conceição','Centro','São Joaquim','Serra Azul','Imaculada Conceição','Masterville','Santa Mônica','Manoel Pinheiro','Vila Satélite']; }
function validatedHoursSchedule(mixed $input,string $existing=''): string {if($input===null)return $existing;if(!is_array($input))fail('Informe horários válidos.');$result=[];foreach(['mon','tue','wed','thu','fri','sat','sun'] as $day){$hours=$input[$day]??null;if(!$hours||(!($hours['open']??'')&&!($hours['close']??'')))continue;if(!is_array($hours)||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',(string)($hours['open']??''))||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',(string)($hours['close']??''))||$hours['open']>=$hours['close'])fail('Confira os horários de abertura e fechamento.');$result[$day]=['open'=>$hours['open'],'close'=>$hours['close']];}return $result?json_encode($result,JSON_UNESCAPED_UNICODE):'';}
function businessPromotions(int $id): array { $b=one('SELECT b.*,p.promotion_limit FROM businesses b JOIN plans p ON p.id=b.plan_id WHERE b.id=?',[$id]); if(!$b||!isLive($b))return [];return query('SELECT * FROM promotions WHERE business_id=? AND starts_at<=? AND expires_at>? ORDER BY created_at DESC LIMIT '.(int)$b['promotion_limit'],[$id,date('Y-m-d H:i:s'),date('Y-m-d H:i:s')])->fetchAll(); }
function queueNotice(array $b,string $key,string $message): void { if(one('SELECT id FROM notifications WHERE dedup_key=?',[$key]))return;try{query('INSERT INTO notifications(business_id,dedup_key,message,created_at) VALUES(?,?,?,?)',[$b['id'],$key,$message,date('Y-m-d H:i:s')]);}catch(PDOException $e){if(!one('SELECT id FROM notifications WHERE dedup_key=?',[$key]))throw $e;} }
function expiryNotice(array $b): ?array {
 $until=validUntil($b);if(isFreeBusiness($b)||!empty($b['is_demo'])||$b['status']==='suspended'||!$until||$until>date('Y-m-d H:i:s',strtotime('+3 days')))return null;
 $expired=$until<=date('Y-m-d H:i:s');$state=$expired?'expired':'soon';$message='Olá! A divulgação de '.$b['name'].' no Sarzedo por perto '.($expired?'expirou em ':'vence em ').date('d/m/Y H:i',strtotime($until)).'. '.($expired?(hasFreeDisplay($b)?'Sua vitrine aparece como Free até '.date('d/m/Y',strtotime(freeDisplayUntil($b))).', sem imagens, publicações e avaliações. ':'Sua vitrine está fora da busca. ').'Renove para recuperar os benefícios do seu plano. ':'Renove para manter sua vitrine disponível. ').'Gere o Pix no painel, pague e envie o comprovante para conferência em https://wa.me/5531987671102 . Acesse '.rtrim(env('APP_URL','http://localhost:8080'),'/').'/#!/painel para consultar seu Pix. Se já pagou, confira o status no painel.';
 return ['key'=>'expiry_'.$b['id'].'_'.$until.'_'.$state,'state'=>$state,'until'=>$until,'message'=>$message];
}
function renewalOverview(): array {
 $items=[];$counts=['soon'=>0,'expired'=>0];$integrations=integrationStatus();
 foreach(query('SELECT b.*,p.name plan FROM businesses b JOIN plans p ON p.id=b.plan_id WHERE b.is_demo=0')->fetchAll() as $b){$notice=expiryNotice($b);if(!$notice)continue;$counts[$notice['state']]++;$record=one('SELECT id,status FROM notifications WHERE dedup_key=?',[$notice['key']]);$deliveries=$record?query('SELECT channel,status,sent_at,last_error FROM deliveries WHERE notification_id=?',[$record['id']])->fetchAll():[];
 $channels=[];if(in_array($b['notification_channel'],['email','both'])&&$integrations['email'])$channels[]='E-mail';if(in_array($b['notification_channel'],['whatsapp','both'])&&$b['whatsapp_consent']&&$integrations['whatsapp'])$channels[]='WhatsApp';
 $items[]=['id'=>$b['id'],'name'=>$b['name'],'plan'=>$b['plan'],'state'=>$notice['state'],'until'=>$notice['until'],'message'=>$notice['message'],'manual_url'=>(manualNotifications()||$b['whatsapp_consent'])?'https://wa.me/55'.$b['phone'].'?text='.rawurlencode($notice['message']):null,'manual_done'=>$record&&$record['status']==='done','automatic'=>$integrations['automation']&&count($channels)>0,'channels'=>$channels,'deliveries'=>$deliveries];}
 usort($items,fn($a,$b)=>strcmp($a['until'],$b['until']));return ['counts'=>$counts,'items'=>$items];
}
function prepareNotifications(): void { foreach(query("SELECT * FROM businesses WHERE is_demo=0 AND status<>'suspended'")->fetchAll() as $b){if(isFreeBusiness($b))continue;$until=validUntil($b);$notice=expiryNotice($b);if($notice)queueNotice($b,$notice['key'],$notice['message']);if(!$until&&$b['activation_deadline']<=date('Y-m-d H:i:s',strtotime('+2 days')))queueNotice($b,'activation_'.$b['id'],'Olá! Seu cadastro no Sarzedo por perto está salvo. Ative a vitrine de '.$b['name'].' com Pix em '.env('APP_URL','http://localhost:8080').'/#!/painel.');} }

// Fixed query definitions only; page input never supplies SQL identifiers.
function adminRecords(string $type, int $page=1): array {
 $queries=[
  'advertisements'=>['a.*,b.name business_name','advertisements a JOIN businesses b ON b.id=a.business_id','1=1','a.id DESC'],
  'ad_orders'=>['o.*,b.name business_name,b.id business_id,a.id advertisement_id','ad_orders o JOIN businesses b ON b.id=o.business_id LEFT JOIN advertisements a ON a.order_id=o.id','1=1','o.id DESC'],
  'audit'=>['a.*,u.name admin_name','admin_audit a JOIN users u ON u.id=a.admin_id','1=1','a.id DESC'],
  'requests'=>['r.*,u.name,u.email','privacy_requests r JOIN users u ON u.id=r.user_id','1=1','r.id DESC'],
  'delivery_log'=>['d.*,n.message,b.name','deliveries d JOIN notifications n ON n.id=d.notification_id JOIN businesses b ON b.id=n.business_id','1=1','d.id DESC'],
  'notifications'=>['n.*,b.name,b.phone','notifications n JOIN businesses b ON b.id=n.business_id',"n.status='pending'".(manualNotifications()?'':' AND b.whatsapp_consent=1'),'n.id DESC'],
  'manual_pending'=>['p.*,b.id business_id,b.name business_name,COALESCE(m.txid,p.provider_id) txid,m.payment_id manual_payment_id','payments p JOIN subscriptions s ON s.id=p.subscription_id JOIN businesses b ON b.id=s.business_id LEFT JOIN manual_pix_payments m ON m.payment_id=p.id',"p.status IN ('PENDING','OVERDUE')",'p.due_date,p.id']
 ];
 if(!isset($queries[$type]))fail('Lista administrativa não encontrada.',404);
 [$select,$from,$where,$order]=$queries[$type];$total=(int)one("SELECT COUNT(*) n FROM $from WHERE $where")['n'];$pages=max(1,(int)ceil($total/25));$page=max(1,min($page,$pages));$offset=($page-1)*25;
 $items=query("SELECT $select FROM $from WHERE $where ORDER BY $order LIMIT 25 OFFSET $offset")->fetchAll();
 if($type==='notifications')foreach($items as &$item)$item['url']='https://wa.me/55'.$item['phone'].'?text='.rawurlencode($item['message']);
 if($type==='advertisements')foreach($items as &$item){$b=one('SELECT * FROM businesses WHERE id=?',[$item['business_id']]);$item['public_visible']=false;if(empty($item['image_url']))$item['visibility_reason']='Envie a imagem de 900 × 600 px.';elseif(empty($item['paid_at']))$item['visibility_reason']='Confirme o pagamento da publicidade.';elseif($item['status']!=='active')$item['visibility_reason']=$item['status']==='paused'?'Publicidade pausada.':'Publicidade ainda não foi ativada.';elseif(empty($item['starts_at'])||$item['starts_at']>date('Y-m-d H:i:s'))$item['visibility_reason']='O período de exibição ainda não começou.';elseif(empty($item['expires_at'])||$item['expires_at']<=date('Y-m-d H:i:s'))$item['visibility_reason']='Publicidade expirada.';elseif(!$b||$b['approval_status']!=='approved')$item['visibility_reason']='Aprove o cadastro do negócio para exibir a publicidade.';elseif($b['status']==='suspended')$item['visibility_reason']='O negócio está suspenso.';elseif(!isListed($b))$item['visibility_reason']='Ative ou renove a exibição do negócio.';else{$item['public_visible']=true;$item['visibility_reason']='Visível na página principal.';}}
 return ['items'=>$items,'page'=>$page,'pages'=>$pages,'total'=>$total,'page_size'=>25];
}

