 if(preg_match('#^/api/admin/businesses/(\d+)/(activate|suspend|restore|approve|reject)$#',$path,$m)&&$method==='POST'){
  $d=input();$reason=field($d,'reason',5,500);$b=one('SELECT * FROM businesses WHERE id=?',[$m[1]]);if(!$b)fail('Cadastro não encontrado.',404);
  transaction(function()use($b,$d,$reason,$m,$admin){lockBusiness((int)$b['id']);if(in_array($m[2],['approve','reject'])){query('UPDATE businesses SET approval_status=? WHERE id=?',[$m[2]==='approve'?'approved':'rejected',$b['id']]);}elseif($m[2]==='activate'){$days=filter_var($d['days']??null,FILTER_VALIDATE_INT);$plan=one('SELECT * FROM plans WHERE id=?',[(int)($d['plan_id']??0)]);if($plan&&isFreePlanId($plan['id']))fail('O Free não exige ativação por prazo. Use retirar suspensão para restaurar um cadastro Free.');if(!$days||$days<1||$days>365||!$plan)fail('Informe plano e validade de 1 a 365 dias.');if(one('SELECT COUNT(*) n FROM photos WHERE business_id=?',[$b['id']])['n']>$plan['photo_limit'])fail('Este plano não comporta a galeria atual.');$until=date('Y-m-d H:i:s',strtotime('+'.$days.' days',max(time(),strtotime(validUntil($b))?:0)));query("UPDATE businesses SET status='active',manual_until=?,plan_id=? WHERE id=?",[$until,$plan['id'],$b['id']]);queueNotice($b,'manual_'.$b['id'].'_'.$until,'Olá! A vitrine de '.$b['name'].' no Sarzedo por perto foi ativada até '.date('d/m/Y',strtotime($until)).'.');}else query('UPDATE businesses SET status=? WHERE id=?',[$m[2]==='suspend'?'suspended':'pending',$b['id']]);audit((int)$admin['id'],(int)$b['id'],$m[2],$reason);});jsonResponse(['ok'=>true]);
 }
 if($path==='/api/admin/settings'&&$method==='POST'){
  $d=input();$start=field($d,'launch_start',0,19);$end=field($d,'launch_end',0,19);if(($start&&!$end)||(!$start&&$end))fail('Preencha início e fim da campanha.');foreach([$start,$end]as$date)if($date&&(!preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/',$date)||date('Y-m-d H:i:s',strtotime($date))!==$date))fail('Informe uma data e hora válidas nos campos da campanha.');if($start&&$end<=$start)fail('O fim da campanha deve ser posterior ao início.');
  $email=field($d,'privacy_email',0,190);if($email&&!filter_var($email,FILTER_VALIDATE_EMAIL))fail('E-mail de privacidade inválido.');$adPrice=isset($d['advertising_price'])?priceInCents($d['advertising_price']):(int)(settings()['advertising_price_cents']??3500);$name=field($d,'controller_name',0,190);$phoneInput=field($d,'support_whatsapp',0,20);if($phoneInput&&!preg_match('/^[0-9 ()+-]+$/',$phoneInput))fail('O WhatsApp deve conter somente números.');$phone=preg_replace('/\D/','',$phoneInput);if($phone&&!in_array(strlen($phone),[10,11,12,13]))fail('Informe um WhatsApp válido com DDD.');$mapsKey=field($d,'maps_embed_key',0,100);if($mapsKey&&!preg_match('/^[A-Za-z0-9_-]{30,100}$/',$mapsKey))fail('Informe uma chave válida da Google Maps Embed API.');
  transaction(function()use($start,$end,$email,$name,$phone,$admin,$adPrice,$mapsKey){foreach(['launch_start'=>$start,'launch_end'=>$end,'privacy_email'=>$email,'controller_name'=>$name,'support_whatsapp'=>$phone,'advertising_price_cents'=>(string)$adPrice,'maps_embed_key'=>$mapsKey]as$k=>$v)query('UPDATE settings SET value=? WHERE setting_key=?',[$v,$k]);audit((int)$admin['id'],null,'settings','Atualização da campanha e canais de atendimento');});jsonResponse(['ok'=>true]);
 }
